public final class FloydWarshall {
    public static final int NO_PATH = Integer.MAX_VALUE;
    public static final int INF = NO_PATH;
    private static final String OVERFLOW_MESSAGE = "Path distance overflowed int range.";

    private FloydWarshall() {
    }

    public static int[][] shortestPaths(int[][] graph) {
        int vertexCount = Matrices.requireSquare(graph, "Graph matrix");
        int[][] distances = Matrices.copyOf(graph);

        for (int via = 0; via < vertexCount; via++) {
            relaxPathsVia(distances, via);
        }

        return distances;
    }

    public static boolean hasNegativeCycle(int[][] distances) {
        Matrices.requireSquare(distances, "Distance matrix");

        for (int index = 0; index < distances.length; index++) {
            if (hasNegativeSelfDistance(distances, index)) {
                return true;
            }
        }

        return false;
    }

    public static boolean isReachable(int distance) {
        return distance != NO_PATH;
    }

    private static void relaxPathsVia(int[][] distances, int via) {
        int[] viaRow = distances[via];
        for (int[] fromRow : distances) {
            relaxRow(fromRow, viaRow, via);
        }
    }

    private static void relaxRow(int[] fromRow, int[] viaRow, int via) {
        int distanceToVia = fromRow[via];
        if (!isReachable(distanceToVia)) {
            return;
        }

        for (int to = 0; to < fromRow.length; to++) {
            relaxDistance(fromRow, viaRow, distanceToVia, to);
        }
    }

    private static void relaxDistance(int[] fromRow, int[] viaRow, int distanceToVia, int to) {
        int distanceFromVia = viaRow[to];
        if (!isReachable(distanceFromVia)) {
            return;
        }

        int candidateDistance = addDistances(distanceToVia, distanceFromVia);
        if (candidateDistance < fromRow[to]) {
            fromRow[to] = candidateDistance;
        }
    }

    private static boolean hasNegativeSelfDistance(int[][] distances, int vertex) {
        return distances[vertex][vertex] < 0;
    }

    private static int addDistances(int left, int right) {
        try {
            return Math.addExact(left, right);
        } catch (ArithmeticException exception) {
            throw new ArithmeticException(OVERFLOW_MESSAGE);
        }
    }
}

import java.util.Arrays;

final class Matrices {
    private static final String NULL_SUFFIX = " must not be null.";
    private static final String NULL_ROW_SUFFIX = " must not contain null rows.";
    private static final String RECTANGULAR_SUFFIX = " must be rectangular.";
    private static final String SQUARE_SUFFIX = " must be square.";

    private Matrices() {
    }

    static int requireSquare(int[][] matrix, String label) {
        int columnCount = requireRectangular(matrix, label);
        if (matrix.length != columnCount) {
            throw new IllegalArgumentException(label + SQUARE_SUFFIX);
        }
        return matrix.length;
    }

    static int requireRectangular(int[][] matrix, String label) {
        requireMatrix(matrix, label);

        if (matrix.length == 0) {
            return 0;
        }

        int columnCount = requireRow(matrix[0], label).length;
        for (int rowIndex = 1; rowIndex < matrix.length; rowIndex++) {
            int[] row = requireRow(matrix[rowIndex], label);
            if (row.length != columnCount) {
                throw new IllegalArgumentException(label + RECTANGULAR_SUFFIX);
            }
        }

        return columnCount;
    }

    static int[][] copyOf(int[][] matrix) {
        requireRectangular(matrix, "Matrix");

        int[][] copy = new int[matrix.length][];
        for (int rowIndex = 0; rowIndex < matrix.length; rowIndex++) {
            copy[rowIndex] = Arrays.copyOf(matrix[rowIndex], matrix[rowIndex].length);
        }

        return copy;
    }

    private static void requireMatrix(int[][] matrix, String label) {
        if (matrix == null) {
            throw new IllegalArgumentException(label + NULL_SUFFIX);
        }
    }

    private static int[] requireRow(int[] row, String label) {
        if (row == null) {
            throw new IllegalArgumentException(label + NULL_ROW_SUFFIX);
        }
        return row;
    }
}

